import { mkdirSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { stringify } from "yaml";

export const FILE_NAMES = ["episodes.yaml", "characters.yaml", "guests.yaml", "fans.yaml"] as const;

export const HEADER =
  "# Generated by pnpm data:import — do not edit. Spoilers: do not open outside the app.\n\n";

/** Deterministic YAML: keys sorted at every level, no line folding. Callers sort the lists. */
export function renderYaml(doc: Record<string, unknown>): string {
  return HEADER + stringify(doc, { sortMapEntries: true, lineWidth: 0 });
}

/** Writes each file through a temp file + rename. */
export function writeGenerated(dir: string, files: Record<string, string>): void {
  mkdirSync(dir, { recursive: true });
  for (const [name, text] of Object.entries(files)) {
    const target = join(dir, name);
    const tmp = `${target}.${process.pid}.tmp`;
    writeFileSync(tmp, text, "utf8");
    renameSync(tmp, target);
  }
}
